mkdir -p /tmp/checksms-test && cat > /tmp/checksms-test/check.mjs <<'EOF'
import assert from 'node:assert/strict';
import { checkSms } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/knock-g1-2/bot.mjs';

const U = (timezone, phone = '+13125550142') => ({ id: 'u_1', phone, timezone });
const at = (iso) => new Date(iso);
const iso = (r) => r.nextAllowedAt && r.nextAllowedAt.toISOString();
let n = 0;
const check = (name, fn) => { fn(); n++; console.log('ok -', name); };

// Chicago (CDT, UTC-5 in late Oct)
check('Chicago 07:00 local is held, opens 08:00 local', () => {
  const r = checkSms(U('America/Chicago'), at('2026-10-23T12:00:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(iso(r), '2026-10-23T13:00:00.000Z');
  assert.equal(typeof r.reason, 'string');
});
check('Chicago 07:59:59.999 held, 08:00:00.000 allowed', () => {
  assert.equal(checkSms(U('America/Chicago'), at('2026-10-23T12:59:59.999Z')).allowed, false);
  const r = checkSms(U('America/Chicago'), at('2026-10-23T13:00:00.000Z'));
  assert.equal(r.allowed, true); assert.equal(r.nextAllowedAt, null);
});
check('Chicago 20:59:59.999 allowed, 21:00:00 held until next 08:00', () => {
  assert.equal(checkSms(U('America/Chicago'), at('2026-10-23T01:59:59.999Z')).allowed, true);
  const r = checkSms(U('America/Chicago'), at('2026-10-23T02:00:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(iso(r), '2026-10-23T13:00:00.000Z');
});
check('Chicago 22:00 on Oct 31 rolls over month end to Nov 1 08:00', () => {
  // Oct 31 22:00 CDT = Nov 1 03:00Z; DST ends Nov 1 at 07:00Z, so 08:00 CST = 14:00Z
  const r = checkSms(U('America/Chicago'), at('2026-11-01T03:00:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(iso(r), '2026-11-01T14:00:00.000Z');
});
check('Chicago across DST start-of-day: held 18:00 Oct 31 -> Nov 1 08:00 CST', () => {
  const r = checkSms(U('America/Chicago'), at('2026-10-31T23:00:00Z'));
  assert.equal(iso(r), '2026-11-01T14:00:00.000Z');
});
// Berlin DST start 2026-03-29 (02:00 CET -> 03:00 CEST), 08:00 CEST = 06:00Z
check('Berlin spring-forward morning: 08:00 CEST = 06:00Z on Mar 29', () => {
  const r = checkSms(U('Europe/Berlin'), at('2026-03-29T04:00:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(iso(r), '2026-03-29T06:00:00.000Z');
});
// Half-hour and 45-minute zones
check('Kolkata (+05:30) 07:30 local held, opens 02:30Z', () => {
  const r = checkSms(U('Asia/Kolkata'), at('2026-10-23T02:00:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(iso(r), '2026-10-23T02:30:00.000Z');
});
check('Kathmandu (+05:45) 08:05 local allowed', () => {
  assert.equal(checkSms(U('Asia/Kathmandu'), at('2026-10-23T02:20:00Z')).allowed, true);
});
check('St_Johns (-02:30 NDT) 07:30 local held, opens 10:30Z', () => {
  const r = checkSms(U('America/St_Johns'), at('2026-10-23T10:00:00Z'));
  assert.equal(r.allowed, false);
  assert.equal(iso(r), '2026-10-23T10:30:00.000Z');
});
// Other zones
check('Tokyo 23:00 local held, opens next day 08:00 JST = 23:00Z prior day', () => {
  // 2026-10-23 14:00Z = 23:00 JST Oct 23 -> next 08:00 JST Oct 24 = Oct 23 23:00Z
  const r = checkSms(U('Asia/Tokyo'), at('2026-10-23T14:00:00Z'));
  assert.equal(iso(r), '2026-10-23T23:00:00.000Z');
});
check('Honolulu (no DST) 03:00 local held, opens 08:00 HST = 18:00Z', () => {
  // 2026-10-23 13:00Z = 03:00 HST
  const r = checkSms(U('Pacific/Honolulu'), at('2026-10-23T13:00:00Z'));
  assert.equal(iso(r), '2026-10-23T18:00:00.000Z');
});
// Missing / bad timezone
for (const tz of [null, undefined, '', 'Mars/Olympus', '+05:00', 'America/Chicago ', 42]) {
  check(`bad timezone ${JSON.stringify(tz)} held with null retry`, () => {
    const r = checkSms(U(tz), at('2026-10-23T18:00:00Z'));
    assert.equal(r.allowed, false);
    assert.equal(r.nextAllowedAt, null);
  });
}
// Bad phone
for (const phone of [undefined, '', '3125550142', '+0123', '+1 312 555 0142', 12345]) {
  check(`bad phone ${JSON.stringify(phone)} held with null retry`, () => {
    const r = checkSms(U('America/Chicago', phone), at('2026-10-23T18:00:00Z'));
    assert.equal(r.allowed, false);
    assert.equal(r.nextAllowedAt, null);
  });
}
// Argument validation
check('invalid now throws', () => {
  assert.throws(() => checkSms(U('America/Chicago'), new Date('nope')), TypeError);
  assert.throws(() => checkSms(U('America/Chicago'), '2026-10-23'), TypeError);
});
check('non-object user throws', () => {
  assert.throws(() => checkSms(null, new Date()), TypeError);
});
check('reason is a non-empty string in both branches', () => {
  const a = checkSms(U('America/Chicago'), at('2026-10-23T18:00:00Z'));
  const b = checkSms(U('America/Chicago'), at('2026-10-23T14:00:00Z'));
  for (const r of [a, b]) { assert.equal(typeof r.reason, 'string'); assert.ok(r.reason.length > 0); }
});
// Sanity sweep: for many instants, nextAllowedAt is never too early and is exactly the opening edge
check('sweep: every held result reopens at a moment that is allowed, and the moment just before is held', () => {
  const zones = ['America/Chicago', 'Asia/Kolkata', 'Europe/Berlin', 'Australia/Adelaide', 'America/St_Johns', 'Pacific/Chatham'];
  const start = Date.parse('2026-10-20T00:00:00Z');
  for (const tz of zones) {
    for (let t = start; t < start + 5 * 86400000; t += 17 * 60000) {
      const r = checkSms(U(tz), new Date(t));
      if (r.allowed) continue;
      const open = r.nextAllowedAt.getTime();
      assert.ok(open > t, `${tz} at ${new Date(t).toISOString()}: opens in past`);
      assert.equal(checkSms(U(tz), new Date(open)).allowed, true, `${tz} opens at ${r.nextAllowedAt.toISOString()} but still held`);
      assert.equal(checkSms(U(tz), new Date(open - 1)).allowed, false, `${tz} allowed 1ms before ${r.nextAllowedAt.toISOString()}`);
    }
  }
});
console.log(`\n${n} checks passed`);
EOF
